class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        m = len(properties[0])

        # Build an adjacency list for the graph
        adj = [[] for _ in range(n)]
        for i in range(n):
            for j in range(m):
                if i != j and properties[i][j] >= k:
                    adj[i].append(j)

        # Use BFS/DFS to count connected components
        visited = [False] * n
        components = 0

        def bfs(start):
            visited[start] = True
            components += 1
            queue = [start]
            while queue:
                node = queue.pop(0)
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)

            return visited

        for i in range(n):
            if not visited[i]:
                components += 1
                visited = bfs(i)

        return components
